let patientsPageSize = 5;

window.openSignedIntakeModal = async (id, name) => {
    Swal.fire({
        title: 'Loading Signed Intake Records...',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
    });

    const res = await ApiService.request(`/api/intake/patient/${id}`);
    if (res.status === 'success' && res.data) {
        const data = res.data;
        const consentSigHtml = data.consent_signature ? `<img src="${data.consent_signature}" style="max-height: 75px; border: 1px solid #cbd5e1; border-radius: 6px; padding: 4px; background: #ffffff;">` : '<span style="color:#94a3b8;">No Signature</span>';
        const hipaaSigHtml = data.hipaa_signature ? `<img src="${data.hipaa_signature}" style="max-height: 75px; border: 1px solid #cbd5e1; border-radius: 6px; padding: 4px; background: #ffffff;">` : '<span style="color:#94a3b8;">No Signature</span>';

        const isApproved = data.status === 'Approved';
        const badgeBg = isApproved ? '#166534' : '#0284c7';
        const badgeText = isApproved ? 'APPROVED & REVIEWED' : 'SUBMITTED (AWAITING REVIEW)';
        const statusTitle = isApproved ? 'Status: Approved & Verified by Staff' : 'Status: Submitted by Patient & Verified';

        Swal.fire({
            title: `Signed Intake Forms — ${name}`,
            width: '720px',
            html: `
                <div style="text-align: left; background: #ffffff; padding: 10px; max-height: 70vh; overflow-y: auto;">
                    <div style="display: flex; align-items: center; justify-content: space-between; background: #f0fdf4; border: 1px solid #bbf7d0; padding: 10px 14px; border-radius: 8px; margin-bottom: 16px;">
                        <div>
                            <span style="font-weight: 700; color: #166534; font-size: 0.95rem;"><i class="fas fa-check-circle"></i> ${statusTitle}</span>
                            <div style="font-size: 0.8rem; color: #475569; margin-top: 2px;">Submitted At: <strong>${data.submitted_at || 'Recently'}</strong></div>
                        </div>
                        <span style="background: ${badgeBg}; color: white; padding: 4px 10px; border-radius: 20px; font-size: 0.75rem; font-weight: 700;">${badgeText}</span>
                    </div>

                    <!-- Form 1: Consent to Treat -->
                    <div style="border: 1px solid #e2e8f0; border-radius: 8px; padding: 14px; margin-bottom: 14px; background: #fafafa;">
                        <h4 style="margin: 0 0 10px 0; font-size: 0.95rem; font-weight: 700; color: #0284c7; display: flex; align-items: center; gap: 8px;">
                            <i class="fas fa-file-contract"></i> 1. Consent for Treatment & Telehealth
                        </h4>
                        
                        <!-- Full Legal Agreement Text -->
                        <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 10px 12px; font-size: 0.82rem; color: #334155; line-height: 1.5; margin-bottom: 12px; max-height: 110px; overflow-y: auto;">
                            <p style="margin:0 0 6px 0;"><strong>1. Consent for Evaluation & Treatment:</strong> I voluntarily consent to evaluation and treatment by the providers and staff at CareHealth Family Medicine. I understand that no guarantee has been made concerning the results of examination or treatment.</p>
                            <p style="margin:0 0 6px 0;"><strong>2. Disclosure of Information:</strong> I authorize the disclosure of medical records necessary to process insurance claims and ongoing care.</p>
                            <p style="margin:0;"><strong>3. Financial Responsibility:</strong> I understand that I am responsible for payment of all charges for services received.</p>
                        </div>

                        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; font-size: 0.85rem; margin-bottom: 10px;">
                            <div><strong>Signed Name:</strong> ${data.consent_name || name}</div>
                            <div><strong>Signed Date:</strong> ${data.consent_signed_date || 'N/A'}</div>
                        </div>
                        <div>
                            <label style="font-size: 0.8rem; font-weight: 700; color: #64748b; display: block; margin-bottom: 4px;">Patient E-Signature:</label>
                            ${consentSigHtml}
                        </div>
                    </div>

                    <!-- Form 2: HIPAA Notice of Privacy Practices -->
                    <div style="border: 1px solid #e2e8f0; border-radius: 8px; padding: 14px; background: #fafafa;">
                        <h4 style="margin: 0 0 10px 0; font-size: 0.95rem; font-weight: 700; color: #0284c7; display: flex; align-items: center; gap: 8px;">
                            <i class="fas fa-user-shield"></i> 2. HIPAA Notice of Privacy Practices
                        </h4>
                        
                        <!-- Full Legal Agreement Text -->
                        <div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 10px 12px; font-size: 0.82rem; color: #334155; line-height: 1.5; margin-bottom: 12px; max-height: 110px; overflow-y: auto;">
                            <p style="margin:0 0 6px 0;">I acknowledge that I have received, read, and understand the Notice of Privacy Practices (NPP) of CareHealth Family Medicine. The NPP describes how my protected health information (PHI) may be used and disclosed and how I can access this information.</p>
                            <ul style="margin:0; padding-left:16px;">
                                <li>Health information may be used for treatment, payment, and health operations.</li>
                                <li>Right to review Notice of Privacy Practices prior to signing.</li>
                                <li>Right to request a copy of Notice of Privacy Practices at any time.</li>
                            </ul>
                        </div>

                        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; font-size: 0.85rem; margin-bottom: 10px;">
                            <div><strong>Signed Name:</strong> ${data.hipaa_name || name}</div>
                            <div><strong>Signed Date:</strong> ${data.hipaa_signed_date || 'N/A'}</div>
                        </div>
                        <div>
                            <label style="font-size: 0.8rem; font-weight: 700; color: #64748b; display: block; margin-bottom: 4px;">Patient E-Signature:</label>
                            ${hipaaSigHtml}
                        </div>
                    </div>
                </div>
            `,
            showCancelButton: !isApproved,
            confirmButtonText: isApproved ? '<i class="fas fa-times"></i> Close Record' : '<i class="fas fa-check-double"></i> Approve & Mark Reviewed',
            confirmButtonColor: isApproved ? '#0284c7' : '#166534',
            cancelButtonText: 'Close Record'
        }).then(async (result) => {
            if (result.isConfirmed && !isApproved && data.id) {
                try {
                    const appRes = await ApiService.request(`/api/intake/approve/${data.id}`, 'POST');
                    if (appRes && appRes.status === 'success') {
                        Toast.show(`Intake forms for "${name}" approved & marked as reviewed!`, 'success');
                        await initPatientsHandler();
                    } else {
                        Toast.show(appRes.message || 'Error approving intake forms.', 'error');
                    }
                } catch (err) {
                    console.error('Approve Intake error:', err);
                    Toast.show('Error approving intake forms.', 'error');
                }
            }
        });
    } else {
        Swal.fire('Notice', 'No signed intake form records found for this patient yet.', 'info');
    }
};

