    function initSignatureCanvas() {
        const canvas = document.getElementById('signature-canvas');
        const clearBtn = document.getElementById('clear-sig-btn');
        const sigPadInput = document.getElementById('sig-pad-input');
        const sigDataUrl = document.getElementById('sig-data-url');
        const sigStatusMsg = document.getElementById('sig-status-msg');
        if (!canvas) return;

        const ctx = canvas.getContext('2d');
        let isDrawing = false;

        const getPos = (e) => {
            const rect = canvas.getBoundingClientRect();
            const touch = (e.touches && e.touches.length > 0) ? e.touches[0] : (e.changedTouches && e.changedTouches.length > 0 ? e.changedTouches[0] : null);
            const clientX = touch ? touch.clientX : (e.clientX !== undefined ? e.clientX : 0);
            const clientY = touch ? touch.clientY : (e.clientY !== undefined ? e.clientY : 0);
            const scaleX = rect.width ? canvas.width / rect.width : 1;
            const scaleY = rect.height ? canvas.height / rect.height : 1;
            return {
                x: (clientX - rect.left) * scaleX,
                y: (clientY - rect.top) * scaleY
            };
        };

        const startDrawing = (e) => {
            if (e && e.preventDefault) e.preventDefault();
            isDrawing = true;
            ctx.beginPath();
            const pos = getPos(e);
            ctx.moveTo(pos.x, pos.y);
        };

        const draw = (e) => {
            if (!isDrawing) return;
            if (e && e.preventDefault) e.preventDefault();
            const pos = getPos(e);
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.strokeStyle = '#0284c7';
            ctx.lineTo(pos.x, pos.y);
            ctx.stroke();
            if (sigStatusMsg) sigStatusMsg.textContent = '✓ Digital signature captured successfully.';
            if (sigDataUrl) sigDataUrl.value = canvas.toDataURL();
            if (sigPadInput) sigPadInput.value = 'Digitally Signed Provider Attestation';
        };

        const stopDrawing = () => {
            if (isDrawing) {
                isDrawing = false;
                ctx.closePath();
            }
        };

        canvas.addEventListener('mousedown', startDrawing);
        canvas.addEventListener('mousemove', draw);
        canvas.addEventListener('mouseup', stopDrawing);
        canvas.addEventListener('mouseleave', stopDrawing);

        canvas.addEventListener('touchstart', startDrawing, { passive: false });
        canvas.addEventListener('touchmove', draw, { passive: false });
        canvas.addEventListener('touchend', stopDrawing);

        if (clearBtn) {
            clearBtn.onclick = () => {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                if (sigStatusMsg) sigStatusMsg.textContent = 'Sign above with mouse or touch screen. No typing required.';
                if (sigDataUrl) sigDataUrl.value = '';
                if (sigPadInput) sigPadInput.value = 'Digitally Signed Provider Attestation';
            };
        }
    }

    // Initialize Canvas Signature Pad
    setTimeout(initSignatureCanvas, 100);

